import{_ as r,o as i,c as t,a3 as s,j as e,a as o}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/vorbereitung/gp-abgeschlossene-faecher-holen.jpg",h="/bilder/vorbereitung/abgeschlossene-facher-individuell.png",f=JSON.parse('{"title":"Abgeschlossene Fächer für Zeugnisse übernehmen","description":"","frontmatter":{"title":"Abgeschlossene Fächer für Zeugnisse übernehmen","source_pageid":789,"source_revision":5410},"headers":[],"relativePath":"zeugnisse/vorbereitung/abgeschlossene-faecher-holen-gruppenprozesse-noten-zeugnisvorbereitung.md","filePath":"zeugnisse/vorbereitung/abgeschlossene-faecher-holen-gruppenprozesse-noten-zeugnisvorbereitung.md"}'),a={name:"zeugnisse/vorbereitung/abgeschlossene-faecher-holen-gruppenprozesse-noten-zeugnisvorbereitung.md"};function g(c,n,u,d,p,b){return i(),t("div",null,[...n[0]||(n[0]=[s('<h1 id="abgeschlossene-facher-fur-zeugnisse-ubernehmen" tabindex="-1">Abgeschlossene Fächer für Zeugnisse übernehmen <a class="header-anchor" href="#abgeschlossene-facher-fur-zeugnisse-ubernehmen" aria-label="Permalink to &quot;Abgeschlossene Fächer für Zeugnisse übernehmen&quot;">​</a></h1><p>Übernehmen Sie früher abgeschlossene Fächer in den aktuellen Abschnitt. Prüfen Sie zuvor die Kennzeichnung im Fachkatalog und die gewünschten Übernahmeoptionen.</p><p>Mithilfe des Gruppenprozesses <strong>Abgeschlossene Fächer holen</strong> aus dem Bereich <em>Gruppenprozesse ➜ Noten, Zeugnisvorbereitung</em> ist es möglich, die abgeschlossenen Fächer für eine ganze Schülergruppe zu holen.</p><p>Mit <em>Abgeschlossene Fächer</em> sind solche Fächer gemeint, die ein/e Schülerin in vergangenen Schuljahren belegt hatte und in denen er/sie benotet wurde, die im aktuellen Schuljahr aber nicht unterrichtet werden.</p><p>Unter <strong>Kataloge ➜ Fächer</strong> markieren Sie in <strong>Sonstige Einstellungen</strong> die Option <strong>Bei „abgeschlossene Fächer holen“ berücksichtigen</strong> für die betreffenden Fächer. Die aktuellen Aufnahmen des Fächerkatalogs und des Übernahmedialogs bestätigen diese Zuordnung.</p>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),o("Hinweis")]),e("p",null,"Die Noten abgeschlossener Fächer finden in der Regel Berücksichtigung in Überweisungs- und Abschlusszeugnissen.")],-1),s('<p><a href="/bilder/vorbereitung/gp-abgeschlossene-faecher-holen.jpg"><img src="'+l+'" alt="Gruppenprozess: Abgeschlossene Fächer holen." loading="lazy"></a></p><p><em>Gruppenprozess: Abgeschlossene Fächer holen.</em></p><p>Sollen entsprechende Zeugnisse für einen ganzen Jahrgang erstellt werden, eignet sich auf jeden Fall die Verwendung des Gruppenprozesses.</p><p>Nach dem Start wählen Sie im Dialog, ob <strong>fachbezogene Bemerkungen</strong> mit übernommen werden und ob die Übernahme auf <strong>Fächer der aktuellen Gliederung</strong> begrenzt wird.</p><p>Mit <strong>Nur Fächer mit Note xx oder besser holen</strong> begrenzen Sie die Übernahme auf die gewählte Note und bessere Noten.</p><p>Da Schüler gegebenenfalls die Möglichkeit haben, &quot;schlechte&quot; Noten aus vergangenen Abschnitten nicht mit auf dem Abschlusszeugnis aufgeführt zu bekommen, ist es sinnvoll, nur Noten &quot;befriedigend&quot; und besser zu holen. Die Fächer mit Note werden dann zusätzlich im aktuellen Abschnitt eingetragen.</p><p><a href="/bilder/vorbereitung/abgeschlossene-facher-individuell.png"><img src="'+h+'" alt="Individuelles Holen abgeschlossener Fächer ohne Gruppenprozess." loading="lazy"></a></p><p><em>Individuelles Holen abgeschlossener Fächer ohne Gruppenprozess.</em></p><p>Muss nur für einen einzelnen Schüler ein Überweisungs- oder Abschlusszeugnis erstellt werden, bietet es sich an, abgeschlossene Fächer individuell für holen. Dies geht über <em>Schüler ➜ Übersicht</em> (eventuell <em>Übersicht SI</em>) mit der rechten Maustaste in die Spalte des aktiven Abschnittes/Halbjahres.</p><p>Im Kontextmenü stehen zwei Möglichkeiten zur Verfügung:</p><ul><li><strong>Abgeschlossene Fächer für Abgangs-/ Überweisungszeugnis holen</strong></li><li><strong>Ausgewähltes abgeschlossenes Fach holen</strong></li></ul><p>Die Noten aus vorherigen Jahren werden dann mit vor- und nachgestelltem * markiert (z.B. *3*).</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Abgeschlossene_F%C3%A4cher_holen_(Gruppenprozesse_Noten,_Zeugnisvorbereitung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5410.</p>',14)])])}const _=r(a,[["render",g]]);export{f as __pageData,_ as default};
